/// Stub macro for unimplemented functions.
/// Prints "STUB: funcname" to stderr and exits with code 99.
#[macro_export]
macro_rules! stub {
    ($name:ident $(, $arg:ident : $ty:ty)*) => {
        #[unsafe(no_mangle)]
        pub extern "C" fn $name($(_: $ty),*) {
            // Write "STUB: funcname\n" to stderr (fd 2)
            const MSG: &[u8] = concat!("STUB: ", stringify!($name), "\n").as_bytes();
            unsafe {
                $crate::syscall::syscall3(
                    $crate::syscall::SYS_WRITE,
                    2,                    // stderr
                    MSG.as_ptr() as u64,
                    MSG.len() as u64,
                );
                $crate::syscall::syscall1($crate::syscall::SYS_EXIT_GROUP, 99);
            }
            // unreachable, but needed for type checking
            #[allow(unreachable_code)]
            loop {}
        }
    };
}

